```python
# Initialize an empty list to store tasks
tasks = []

def add_task():
    """Add a new task to the list."""
    task_id = int(input("Enter a task ID: "))
    task_description = input("Enter the task description: ")
    tasks.append({"id": task_id, "description": task_description, "completed": False})
    print(f"Task {task_id} added.")

def remove_task():
    """Remove a task from the list based on its ID."""
    task_id = int(input("Enter the task ID to remove: "))
    if task_id in [task["id"] for task in tasks]:
        tasks.remove(next((task for task in tasks if task["id"] == task_id), None))
        print(f"Task {task_id} removed.")
    else:
        print("Task not found.")

def mark_task_completed():
    """Mark a task as completed based on its ID."""
    task_id = int(input("Enter the task ID to mark as completed: "))
    if task_id in [task["id"] for task in tasks]:
        tasks[tasks.index(next((task for task in tasks if task["id"] == task_id), None))]["completed"] = True
        print(f"Task {task_id} completed.")
    else:
        print("Task not found.")

def print_tasks():
    """Print all tasks in the list."""
    print("\nTasks:")
    for task in tasks:
        print(f"{task['id']}. {task['description']}")

while True:
    print("\nAvailable tasks:")
    print_tasks()

    command = input("\nEnter a command (add, remove, mark, or exit): ").lower()

    if command == "add":
        add_task()
    elif command == "remove":
        remove_task()
    elif command == "mark":
        mark_task_completed()
    elif command == "exit":
        break
    else:
        print("Invalid command. Please try again.")

print("\nGoodbye!")
```

This program defines three functions (`add_task()`, `remove_task()`, and `mark_task_completed()`) that perform the desired operations. The main part of the program uses a while loop to continuously prompt the user for commands and execute the corresponding functions.
